  const parsed = parseBoardCode(boardCode);
  if (!parsed) return null;
  const { size, seed } = parsed;
  const deck = Array.from({ length: size * size }, (_, i) => Math.floor(i / 2));
  let random = seed;
  for (let i = deck.length - 1; i > 0; i--) {
